-- Run as schema owner after creating LOGIN roles crm_runtime and crm_preview_runtime.
-- Credentials are generated by Neon and managed as environment secrets.
GRANT USAGE ON SCHEMA crm TO crm_runtime;
GRANT SELECT, INSERT, UPDATE ON crm.opportunities TO crm_runtime;
GRANT SELECT, INSERT, UPDATE, DELETE ON crm.rate_limits TO crm_runtime;

GRANT USAGE ON SCHEMA crm_preview TO crm_preview_runtime;
GRANT SELECT, INSERT, UPDATE ON crm_preview.opportunities TO crm_preview_runtime;
GRANT SELECT, INSERT, UPDATE, DELETE ON crm_preview.rate_limits TO crm_preview_runtime;
